mapper.select:
SELECT transaction_id, wallet_id, player_id, transaction_type, amount, balance_before, balance_after, request_id, reference_type, reference_id, description, create_time FROM t_wallet_transaction
wallet_id = #{query.walletId}
AND transaction_type = #{query.transactionType}
AND create_time >= #{query.startTime}
AND create_time < #{query.endTime}
ORDER BY create_time DESC
